quests[35262] = { id = 35262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Service of Rangari Kaalya", objectives = "Commander, your skills at survival are to be commended but they have many blind spots.\n\nYou need a rangari like myself to help your forces or Draenor is going to eat you up like a goren with a rock.\n\nWill you accept my offer?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35264] = { id = 35264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Bunch of Artifact Fragments", progress = "The more, the better!", completion = "That must of taken great effort to get back to us. You deserve this reward, friend." }
quests[35265] = { id = 35265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ritual of Binding", description = "The time has come for you to undertake the Ritual of Binding, {name}.\n\nThis ancient, shamanic rite has been practiced since long before I was born. To be chosen is a great honor.\n\nMany shaman see vivid elemental visions during the rite; experiencing this world through the very elemental bonds that hold it together.\n\nWhen you are ready, speak with Kalandrios to begin the rite.", progress = "Tell me of your vision, {name}. What did the elements reveal?", completion = "<Farseer Drek'Thar listens closely as you speak of your vision.>\n\nI see... these are truly dark days. Cho'gall has invaded the heart of Oshu'gun, draining the naaru of its life. He seeks to destroy the naaru, birthing a dark, void god in its place.\n\nCho'gall must be stopped. Come, we must travel to the sacred mountain before it is too late.", objectives = "Speak with Kalandrios to begin the Ritual of Binding.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35266] = { id = 35266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Boosted Character" }
quests[35267] = { id = 35267, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ashran Test" }
quests[35271] = { id = 35271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warsong Threat", description = "<The attack plans are scrawled onto the parchment in thick, black ink and bound in rough leather.>\n\nTo all outrider stations:\n\nThe warlord has commanded that all outriders prepare for a full assault upon the Horde invaders in our land. Plans for the attack have been delivered to several of the remote outrider posts.\n\nBlood and glory shall be ours as we trample the Horde invaders beneath our feet!\n\nThe warlord commands and the Warsong obey! Lok'tar ogar!", progress = "What do you have for me?", completion = "<Blood Guard Ehanes looks over the attack plans.>\n\nHmm... I see. You have done well to retrieve these attack plans. With the plans in our hands, we will be more than prepared to counter the assault when it comes.", objectives = "Steal the Warsong Attack Plans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35272] = { id = 35272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One of Our Own", description = "Da bird-men captured me while I was gettin' da lay a da land.\n\nWe been workin' on an outpost for you just round dis mountain so your will be spreadin' all over da continent.\n\nThings not be goin' well.\n\nI be needin' your assistance, commander. Can you tell dem that I mean no harm so I can be showin' you da outpost?", progress = "You be savin' my hide, commander.", completion = "Thank da spirits you showed up. Dey hear my prayers.", objectives = "Speak to Shadow-Sage Iskar and convince him to let Shadow Hunter Ukambe free.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35273] = { id = 35273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hot Seat", description = "<Apexis constructs are about to emerge from their ancient chambers on a warpath. The arakkoa are sure to send more sol-shapers to support them.\n\nThe interface and the turret hum in soft resonance.>", completion = "Ahh, well done. Even with my condition, I could sense the carnage from here.\n\nIt must have been quite a show, kah-hah-haww.", objectives = "Use the Overseer's Chair to take control of the Apexis Turret and slay 20 Apexis Destroyers and 30 Adherent Sol-Shapers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35274] = { id = 35274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One of Our Own", description = "These wretched creatures captured me while I was scouting the area. Now that you're here, commander, we could really use your help back at base.\n\nOh, and any way you could convince your... friends... to let me go?\n\nThey, uh... won't let me leave.", progress = "I had really hoped to have given you a better impression when you came out here.", completion = "Now, uh... could we maybe forget this little incident happened, commander?\n\nBodrick and the other agents would never let me live this down.", objectives = "Speak to Shadow-Sage Iskar and convince him to let Jasper Fel free.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35275] = { id = 35275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inspecting the Troops", description = "Axefall be just a moment's ride from here.\n\nI be markin' da location on your map and meet you dere.", completion = "Our lives for your will, commander.", objectives = "Speak to Shadow Hunter Ukambe at Axefall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35276] = { id = 35276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inspecting the Troops", description = "Southport lies not far from here to the southwest.\n\nNo time for chit-chat. I will meet you there, commander.", completion = "I hope everything is to your liking. It's been one hell of a job.", objectives = "Speak to Jasper Fel at Southport.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35277] = { id = 35277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orders, Commander?", description = "Commander, our status report is... regrettable.\n\nWe'll be out of supplies in a few days' time, and that's assuming we have any troops left by then. \n\nThere's just enough material left to put up an inn or a trading post.\n\nThe inn would allow us to station fresh troops here, but the trading post would open up potential supply routes with the outcasts nearby.\n\nI've left out Gazlowe's blueprints on the drafting table. We await your will.", progress = "Have you made a choice, commander?\n\nGive the word and it will be done.", completion = "Your will be done.\n\nFor the Horde!", objectives = "Inspect the Drafting Table and choose which outpost structure to construct.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35279] = { id = 35279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Shadowmoon Treasure 01" }
