quests[35284] = { id = 35284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trading Post" }
quests[35285] = { id = 35285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Follow that Hotrod!", description = "Miss Kimzee is one tough nugget but Pinchwhistle Point is too dangerous for her to handle alone. It'll be a catastrophe for morale if our boss gets infected.\n\nI need to get these crewmen back to the Gearworks so I need you to go and make sure she is alright.\n\nHer uncle's place is the tower just on the other side of the oil fields; I think you should look for her around there.", completion = "I have good news and bad news.\n\nThe good news is my uncle's alive! The bad news is his leg is injured and we're surrounded by infected! With my hotrod wrecked we can't get him out of here.", objectives = "Find Kimzee Pinchwhistle in Pinchwhistle Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35286] = { id = 35286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orders, Commander?", description = "Commander {name}, it's an honor.\n\nWe're barely holding on, <sir/madame>. We have a week's supplies at best, assuming we have any troops left to supply in that time.\n\nWe have just enough material left to put up an inn or a trading post.\n\nThe inn would allow us to station reinforcements here, while the trading post would allow supply routes with the outcasts nearby.\n\nWe need your authorization for the project, commander. It's your decision.", progress = "Glory to your forces, commander.", completion = "Praise the Light you're here. I thought we were going to have to wait until a courier could reach you for a decision on this.", objectives = "Inspect the Drafting Table and choose which outpost structure to construct.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35287] = { id = 35287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ragefire Chasm Reward Quest" }
