quests[35294] = { id = 35294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jasper Moves" }
quests[35295] = { id = 35295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What's Theirs is Ours", description = "I found somethin' else while I was scoutin', boss.\n\nDa Alliance have a garrison just across da way, and der been no movement in or out of da place in a good while.\n\nDis be a golden opportunity to sack da place and bolster your coffers, commander.\n\nWhat do ya say? We do it together.", completion = "Everyone be dead, mon. What did dis?", objectives = "Speak to Shadow Hunter Ukambe at Admiral Taylor's Garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35296] = { id = 35296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tainted Garden", description = "The abandonded mine shaft has been overrun with Goren!  They seem to be responding to commands from a big one further down in the mine.  If you can take him out, the rest will probably retreat.\n\nOnce you have those Goren cleared out, we can get that mine up and working!You will learn:", objectives = "Kill Stonetooth in the Garrison Mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35297] = { id = 35297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Army Pushed" }
quests[35298] = { id = 35298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flame On", description = "Alright {name}, we've saved as many as we could but now we need to make sure this disaster doesn't spread any further.\n\nThe firebombs are wired up and ready to go.\n\nKimzee just finished work on the flying machine so we're ready to ride back to the Gearworks as soon as we're finished.\n\nYou've done all the hard work so I think you should get the honors of triggering it.", completion = "{name}, you did fantastic work.\n\nEveryone here at the Gearworks owes you big time for what you've done for us.\n\nHere, I want to give you little something. Think of it as a personal token of my gratitude.", objectives = "Use the Firebomb Plunger then ride on Kimzee's Flying Machine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35303] = { id = 35303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wailing Caverns Reward Quest" }
