quests[35371] = { id = 35371, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Ogre Booty 005" }
quests[35372] = { id = 35372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of Oshu'gun", description = "The elements have spoken and a vision has been revealed, {name}.\n\nTogether we shall travel to the great mountain Oshu'gun and put an end to the dark disturbance there.\n\nIf what you saw in the vision is to be believed, then great danger awaits us.\n\nI will meet you in the Spirit Woods at the foot of Oshu'gun. When you are ready to depart, speak with Gixmo Moneycash and he will fly you to there.", completion = "These woods are sacred to the orcs and to my people as well.\n\nBeneath the great mountain of Oshu'gun lies the heart of Nagrand, the Genedar. This great dimensional vessel rescued my people from annihilation and brought us to this world.", objectives = "Fly to the Spirit Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35373] = { id = 35373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Ogre Booty 006" }
quests[35374] = { id = 35374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "That Pounding Sound", description = "Commander. The frostwolf and I were just discussing the merits of various 'hunting' approaches.\n\nI assured her that the shadow hunters are well-equipped to deal with any situation, even ones out in the wild.\n\nShe seems to think that we don't know what we're doing when it comes to bringing down game in 'her land.'\n\nWe're not going to let her get away with saying that, right? Let's take down some clefthoof.", progress = "It's unbelievable how arrogant these frostwolves can be.", completion = "Twelve pairs, huh? That's pretty good, commander.\n\nUm, no, I think that's about how many I managed to bag. Yeah... about a dozen pairs of ears. Yep....", objectives = "Collect 12 Pairs of Leatherhide Ears from Leatherhide clefthoof.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35375] = { id = 35375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Queen of the Clefthoof", description = "Ogka told me that they have Banthar here! Or rather, that she's still alive back now. Did what I just said make any sense?\n\nThis is our chance, commander. We can defeat a younger, more powerful version of Banthar and really stick it to these frostwolves.\n\nWe'll show Ogka how a true professional works.", progress = "Banthar's horn. Hemet would be green with envy to have another shot at such a powerful beast.", completion = "Magnificent kill, commander. You've done us all proud.", objectives = "Collect the Horn of Banthar from Banthar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35376] = { id = 35376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shooting the Breeze", description = "Taz and I are having a spirited debate over who kills more efficiently: shadow hunters or frostwolves.\n\nCare to get in on the wager, commander?\n\nI've been focusing on talbuk because of their fierce majesty. They truly encapsulate the grandeur of Nagrand as any native of Draenor knows.", progress = "This outsider really thinks he can come here and best me in my own land?\n\nOh... sorry, commander. Present company excluded, of course.", completion = "Twenty-four, huh? That's fine work.\n\nI brought back fifty.\n\nI'll send someone out for the meat. Waste not, want not.", objectives = "Collect 24 Breezestrider Horns from Breezestrider talbuk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35377] = { id = 35377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Someone's Missing Axe", description = "<A throwing axe of frostwolf make is sticking out of the side of this talbuk. Perhaps Stalker Ogka will be interested in your find.>", completion = "That's MY axe! Where'd you get it?", objectives = "Take the Frostwolf Axe to Stalker Ogka at Wor'var.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35378] = { id = 35378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "King of the Breezestriders", description = "Let me guess, you found it in a talbuk's flank?\n\n<Ogka seems lost in thought for a moment.>\n\nThat axe was intended for Tall Buck, king of the Breezestriders. Another talbuk - the one you killed - jumped in the way as I was taking my shot.\n\nI suggest you go after the king. When I was hunting him, he seemed fond of the pond at Lonely Falls to the south.", progress = "How goes the hunt for Tall Buck?", completion = "Well done, {name}. You succeeded where I did not.\n\nPerhaps you outsiders aren't such bad hunters after all.", objectives = "Collect Tall Buck's Tail from Tall Buck.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35379] = { id = 35379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hemet's Happy Hunting Grounds" }
quests[35380] = { id = 35380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Second in Command", description = "Wait... I remember something else.\n\nSir Edward... he was shouting... looking for someone.\n\nI... I can't remember who. There were so many screams...", completion = "If today was any other day I'd have you court-martialed for being out of uniform.", objectives = "Speak to Sir Edward at Admiral Taylor's Garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35381] = { id = 35381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Shadowmoon Treasure 05" }
quests[35382] = { id = 35382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Shadowmoon Treasure 06" }
quests[35383] = { id = 35383, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Shadowmoon Treasure 07" }
quests[35384] = { id = 35384, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Shadowmoon Treasure 08" }
quests[35386] = { id = 35386, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warsong Threat", description = "<The attack plans are scrawled onto the parchment in thick, black ink and bound in rough leather.>\n\nTo all outrider stations:\n\nThe warlord has commanded that all outriders prepare for a full assault upon the Alliance invaders in our land. Plans for the attack have been delivered to several of the remote outrider posts.\n\nBlood and glory shall be ours as we trample the Alliance invaders beneath our feet!\n\nThe warlord commands and the Warsong obey! Lok'tar ogar!", progress = "What do you have for me?", completion = "<Captain Washburn examines the attack plans, squinting at the lettering and holding the pages upside down.>\n\nHmm... I see... yes... indeed!\n\nThese are obviously attack plans, as you yourself have stated, but they are most likely written by kobold pyromancers.\n\nStrange though, I haven't seen any kobold pyromancers since my days in Azeroth. No matter! I assure you that the outpost is well armed and mostly fireproof!\n\nIf we are attacked, the outpost shan't fall. You have my word, commander!", objectives = "Steal the Warsong Attack Plans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35387] = { id = 35387, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through The Nether", description = "The void rituals have been disrupted, but dark energy still flows into the nether beacons at the ritual sites. This can only mean that the beacons are being powered from within the Twisting Nether itself.\n\nThe only way to sever the flow of void energy to the beacons is to travel into the Twisting Nether and stop whatever power lurks there!\n\nUse a beacon to travel to the Twisting Nether. Once there, us the shaman stone given to us by the furies to contact me.\n\nLight be with you.", objectives = "Travel to the Twisting Nether.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35388] = { id = 35388, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Void March", description = "Legions of void terrors are marching upon Oshu'gun and sacrificing themselves to the void lord Invalidus.\n\nAs they die Invalidus grows stronger. It is as if the lesser creatures only serve to feed the void lord.\n\nWe must stop Invalidus from becoming so powerful that it cannot be stopped.\n\nSlay as many void monsters as you can, to slow the growth of Invalidus. In the meantime, I will search for a way to encounter Invalidus before it is too late to stop it.", objectives = "Destroy 12 Void Creatures.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35389] = { id = 35389, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silence The Call", description = "The Warsong shaman are using the elements to channel dark energy from the void.\n\nI am no shaman, but even I know that such practices are abhored by most orc clans. The power of the void is opposite to the Light, and a source of entropy and destruction.\n\nThese rituals thin the veil between our world and the Twisting Nether. Should the rituals continue, this land will soon be overrun by the denizens of the Twisting Nether.\n\nSlay the shaman leading these dark rituals before destruction falls upon us!", objectives = "Slay the Warsong ritual leaders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35390] = { id = 35390, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow Over Oshu'gun", description = "The void lord Invalidus stands atop the peak of Oshu'gun gorging itself upon the souls of the dead.\n\nEven the fallen void terrors that you slew only served to feed the monster.\n\nIf we do not act now, Invalidus will grow too powerful to encounter alone.\n\nAt each of the ritual sites in the Twisting Nether, there is a crystal filled with the powers of the void. Disturb the void crystal and Invalidus will sense your presence.\n\nBe ready, Invalidus will waste no time in attempting to feed on your soul.", objectives = "Summon and defeat Invalidus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35391] = { id = 35391, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disrupt The Rituals", description = "Beneath the mountain of Oshu'gun the Warsong perform dark rituals.\n\nThe Warsong shaman seek to empower their clan by drawing upon a great source of void energy within the heart of Oshu'gun.\n\nThough I do not know for certain the source of this power...I fear that the dying naaru K'ure may be involved.\n\nThe Warsong rituals must be stopped or the veil that separates this world from the Twisting Nether will be ripped apart.\n\nLocate the ritual totems used to channel these rituals and destroy them.", objectives = "Destroy the Ritual Totems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35392] = { id = 35392, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nether Approaches", description = "By drawing upon the power of the void, the Warsong have thinned the veil that shields our world from the Twisting Nether.\n\nPortals are opening within the nether that threaten to connect the terrors of the void to Draenor.\n\nShould these portals fully open, the path will be clear for all manner of demons and void creatures to rampage across Nagrand.\n\nGo and collapse the portals before they become functional!", objectives = "Collapse 10 Void Portals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35393] = { id = 35393, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiritual Matters", description = "The spirits of the dead have long been drawn to the mountain of Oshu'gun.\n\nAs long as I can remember, the woods have been filled with ancestral spirits making a ghostly pilgrimage to the heart of the mountain. I fear that the souls drawn to Oshu'gun are being consumed by the growing void within the mountain.\n\nMake your way to the Ancestral Grounds and commune with the spirits there for guidance.", completion = "The situation here is dire, {name}, but I sensed that we would meet again.\n\nI do not hear the call of the void as loudly as the others, for I am not long dead and my body rests far from this place.\n\nWith time though, that will change.\n\nIf you are here to help, listen closely for time is short.", objectives = "Speak with the spirits at the Ancestral Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35394] = { id = 35394, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pale Threat", description = "In the time that you have been fighting against the void, I have been exploring the disturbance within Shadowfall Canyon.\n\nA dark mist has settled in the canyon, {name}; and I found twisted, pale creatures lurking there.\n\nWe have much to discuss. Return to me from the Twisting Nether and we will speak more.", sourceObjective = "Return to Vindicator Nobundo.", sourceObjectiveStatus = "unverified-source-field" }
quests[35395] = { id = 35395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Fate of Gordawg", description = "Looming monstrously between us and the inner chamber is the great fury we have sought to return to the Throne of Elements.\n\nGordawg stands before us enthralled; a slave to Cho'gall. My heart is heavy with grief to see such a great creature mindless and enslaved by evil.\n\nThere is no going back, in order to push forward you must go through Gordawg.\n\nIt pains me, but Gordawg must be slain.\n\nSlay Gordawg and return the fury's heart to the Throne of Elements where it belongs.", progress = "What of Gordawg? Has the great fury been brought to rest?", completion = "Gordawg was a mighty ally. The elements will mourn the loss of the fury, but death was the only answer. Gordawg would not have wished to stay a slave to evil.\n\nThough Gordawg is no more, the heart of a fury is eternal and unbreakable. In time, this brightly glowing heart will take shape into a new earthen fury.\n\nSuch is the cycle of life upon the Elemental Plateau.", objectives = "Retrieve the Heart of the Fury.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35396] = { id = 35396, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Heart of Oshu'gun", description = "Amongst the timeworn wreckage of the Genedar is the entrance to the vessel's inner chamber. The void energy appears to be most concentrated in that place.\n\nYou must enter the inner chamber and face whatever evil lurks within. I fear whatever fate may have befallen the great naaru K'ure in that place, but regardless the evil there must be purged.\n\nMay the Light be with you, {name}.", completion = "The fate of K'ure could not have been prevented.\n\nCho'gall accelerated the naaru's transition into a void god in hopes of bringing destruction upon Draenor. Cho'gall must be dealt with, but for now let us honor the memory of the great naaru K'ure.\n\nK'ure was truly the savior of my people, a friend to the virtuous, and a teacher of prophets.\n\nMay the great naaru ever live within our hearts.", objectives = "Enter the Sanctum of the Naaru.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35397] = { id = 35397, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pale Threat", description = "If we are to succeed in stopping Cho'gall from destroying the naaru, we will need to fight our way through the Underpale; a dark, winding cavern infested with the Pale.\n\nThe Pale are fallen orcs that despise all that is good and holy. The longer they are left to their devices beneath the ground, the further their dark plots progress.\n\nMake your way into the Underpale, slay the vile creatures within and take out their leader, Greyseer.", completion = "The Pale are wretched creatures that hate the Light and plot against the innocent. Without Greyseer to lead them, they will be disorganized and in chaos for a time.\n\nShould a new leader arise from within their ranks, we shall smite them down once more.", objectives = "Kill Greyseer and 6 Pale orcs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35398] = { id = 35398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Binding", description = "Even as we speak, the pale are enslaving an army of elementals in Shadowfall Canyon. Many have already been enslaved and if we do not lend our aid, more will follow.\n\nGo to Shadowfall Canyon and set free the elemental spirits which are not yet fully enthralled by the pale. As for those already enslaved, the only mercy we can give them now is a swift death.", completion = "You have done well to free the elemental spirits from their bonds. If Cho'gall and the pale seek an army of elemental slaves, they must not be allowed to succeed.", objectives = "Free 8 elemental spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35399] = { id = 35399, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mossy Fate", description = "Your wolf queen will not let me out of her sight.\n\nThe children of the magnaron may have destroyed my village but it was the children of the genesaur who took my people.\n\nThe botani and their minions drag our people to the Razorbloom, and if we see them again, it is not as they were in life.\n\nYou have already helped the Skulls, so I ask your help again.\n\nEnter the Razorbloom and search for my people that were recently taken.\n\nPerhaps they may even be alive.", completion = "Dead? All dead? Dead and mulched and forgotten. No Chag with his missing nose or Meka with her love for chewing faces.\n\nAnd Torg, my beloved Torg. A son we had together. A son that is still missing.\n\nThe botani will pay for this. They will burn for this.", objectives = "Search for Torg Earkeeper, Meka the Face Chewer, and Chag the Noseless in Razorbloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35400] = { id = 35400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Infested", description = "I understand Kaz's desire to rescue her people, but her plan is reckless and she is not telling us everything.\n\nI came along to make sure she wasn't devising a plan against us and now I see this... this... horror.\n\nWhat did the botani do to these orcs?\n\nThese infested souls need to be put to rest. Give them peace.", completion = "These creatures... were not what I expected to see. I always knew Gorgrond to be a dangerous place, but I never could have guessed at how vile.\n\nThank you, commander, for your compassion in this.", objectives = "Slay 6 Infested Orcs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35401] = { id = 35401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vortex Pinnacle Reward Quest" }
quests[35402] = { id = 35402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Voice of Iyu", description = "The botani and their wretched minions take and take and take.\n\nThey want food, they take our land. They want an army, they take our people.\n\nIt is important to strike fear into the shrubby hearts of these plant people.\n\nLook for their leader, the Voice of Iyu. It is a botani who speaks on behalf of their genesaur master.\n\nKill their precious leader in the safety of his precious bloom.", completion = "It isn't enough to kill the botani. They will always have greater numbers.\n\nYou must cut them deep and hard, where it hurts them the most.\n\nLike slaying their most sacred leader.", objectives = "Slay the Voice of Iyu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35403] = { id = 35403, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Vortex Pinnacle Reward Quest" }
quests[35404] = { id = 35404, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grim Batol Reward Quest" }
quests[35405] = { id = 35405, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grim Batol Reward Quest" }
quests[35406] = { id = 35406, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Super Seeds", description = "These seeds have been shielded with care by the botani.\n\nGreat power can be felt surging out of these tiny vessels of life.\n\nThese may prove useful.", progress = "What have you found?", completion = "Seeds. So simple to look at but in each the potential for untold amounts of destruction. Much like my son.\n\nYou were wise to take these.", objectives = "Collect Enriched Seeds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35407] = { id = 35407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Punishable by Death", description = "Traitors, the lot!\n\nYou're looking at the last bastion of forces still loyal to Admiral Taylor and the Alliance.\n\nI'll be damned if the defectors get away clean.\n\nYou look like you're ready. Show them how we deal with their kind during times of war.", completion = "Well fought. For the Alliance!", objectives = "Kill 8 garrison traitors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35408] = { id = 35408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prime the Cannons", description = "The armory is lost to the traitors. All we have left are these few cannons with no ammunition.\n\nSoldier, I need you to recover cannonballs so we can get these things running.\n\nActually, one more cannon wouldn't hurt, either.", progress = "I hope you're toting a cannon and some balls, soldier.", completion = "Good job, soldier.", objectives = "Recover 10 Ironcoat Cannonballs and 1 Armory Cannon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35411] = { id = 35411, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zul'Gurub Reward Quest" }
