quests[35415] = { id = 35415, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Origination Reward Quest" }
quests[35416] = { id = 35416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power of the Genesaur", description = "Commander, you now have the Will of the Genesaur along with the genesis water and enough seeds to grow an army. Not to mention the Laughing Skulls you helped save.\n\nI would call this mission a success.\n\nI will investigate this fortress further and see if there are more materials we might glean from it.\n\nIn the meantime, you may want to bring these artifacts you have obtained to Durotan back at the outpost. I will catch up once we have finished here.", completion = "Well done, Commander. Many of the orcs have tried to master the power of the genesaur but I have never heard of any succeeding.\n\nYou have won us a powerful weapon for the next time we face the Iron Horde.", objectives = "Speak with Durotan at Beastwatch in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35420] = { id = 35420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Origination Bonus Rewards" }
quests[35424] = { id = 35424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Origination Reward Quest" }
quests[35426] = { id = 35426, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Origination Bonus Rewards" }
quests[35429] = { id = 35429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pollen Power", description = "Those of us who grew up in Gorgrond have long learned a few secrets of the botani that can be used to grow our own plants.\n\nThere is no such thing as a hungry Laughing Skull for this reason.\n\nThe ravagers are the key.\n\nOutside of Evermorn Springs you will find ravagers of every type. Slay them and bring me the pollen they carry, and I can cultivate it to be of use to your garrison.", progress = "Few dare challenge the botani in the field of growing plants.", completion = "Ah... yes, yes, yes. Fresh pollen. With a dash of a few secret ingredients you can feed an army with the food you could grow from this, if you know the secret ways.", objectives = "Collect 20 Potent Pollen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35430] = { id = 35430, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cutter", description = "You found many Laughing Skulls. All friends, all loved, all dead. But you did not find my precious Cutter.\n\nThey must have taken him to Evermorn Springs.\n\nFind him, and rescue him.\n\nHe is a good boy, and deserves a better death than infesting.\n\nI am going to round up some ravagers and take the place by air. Look for me in Evermorn if you find Cutter before I do.", completion = "The botani took my dad. They took my friends. And now they are making me eat fruit!\n\nWhy are they so mean?!\n\nDid you kill them all?\n\nI think you should kill them.", objectives = "Find Cutter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35431] = { id = 35431, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Best Poison", description = "Do you like poisons? I am more of a \"set everything on fire and loot what doesn't burn\" kind of orc myself.\n\nBut I do know a thing or two about poisons.\n\nWhen you venture into the Razor Bloom, look for a pungent, violent plant that we call Reaver Vine. Under just the right circumstances, and FIRE, the vine will make a lovely poison. Bring me some and I shall concoct a lovely poison for you.", objectives = "Collect 8 Reaver Vines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35432] = { id = 35432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bushwhacker", description = "Kaz is using us, I am sure of it. She is a Laughing Skull and must NOT be trusted.\n\nFor now, I am willing to play along until we can learn more. \n\nKaz is going to ask for you to travel to Evermorn Springs. When there, I recommend you slay any botani you encounter.\n\nCulling the numbers of these horrific casters will hopefully save future orcs from such a infested fate.\n\nI will stay with Kaz and keep a close eye on her.", completion = "I had thought the Laughing Skull were planning something. Now I think I am beginning to understand.\n\nThey match savagery with savagery.", objectives = "Slay 7 Bloom Weavers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35433] = { id = 35433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cut Them Down", description = "They steal children? Children?!\n\nHad you not rescued Kaz's child, he would be reduced to mulch just like the others.\n\nYou should send them a message they will understand. Cut down their great dew casters. Rip them apart.\n\nLet them know that it is not okay to take our children.", completion = "They are lucky you are the one that killed them. I would have tried to carve pictures in their dead wood bodies.", objectives = "Slay 3 Dew Masters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35434] = { id = 35434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Life Spring", description = "It sounds like these... \"dwarves\"... you found managed to steal a powerful botani artifact.\n\nBut the fools didn't know they need a special water to power it.\n\nTo the north is a well along the Evermorn Rise.\n\nThere you will find a guardian, a creature of water we have named Utrophis.\n\nSlay it and take its essence and you will be one step closer to claiming the power of the botani and their genesaur.", progress = "For years the Laughing Skull would not touch the sacred waters. We feared the wrath of the botani. We should have set them to burn long ago.", completion = "The Waters of Utrophis. I have never held or smelled or tasted it before. But I have heard many stories, many legends.\n\nI was expecting something more grand.", objectives = "Collect the Waters of Utrophis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35435] = { id = 35435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Well of Eternity Reward Quest" }
