quests[35444] = { id = 35444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Southern Wilds", description = "First the Iron Horde, then the Shadowmoon orcs, and now there's trouble brewing to the south!\n\nMy brother is a feyrider to the south, at the Draakorium.\n\nHe says that creatures from the swamp are venturing onto our lands. What is this world coming to?\n\nAnyway, you look like a seasoned adventurer. If you are heading that way, would you mind checking in over there?", completion = "Thank you for coming to our aid.", objectives = "Speak to Prelate Reenu at The Draakorium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35446] = { id = 35446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Oculus Reward Quest" }
quests[35447] = { id = 35447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Oculus Reward Quest" }
quests[35448] = { id = 35448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Darkmaster Go'vid" }
quests[35449] = { id = 35449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Utgarde Pinnacle Reward Quest" }
quests[35450] = { id = 35450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Southern Wilds", description = "I've heard disturbing news from our friends at The Draakorium, to the south.\n\nThe town lies near a swamp, and recently, dangerous creatures have been venturing near its borders.\n\nYou seem like a seasoned adventurer. If you are heading that way, would you mind checking in with our people there?\n\nI would feel much better if I knew they were safe.", completion = "Ah, Prelate Luari sent you, did she? Such a sweet woman, always looking out for others.", objectives = "Speak to Prelate Reenu at The Draakorium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35452] = { id = 35452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Utgarde Pinnacle - Bonus Objective Reward" }
