quests[35457] = { id = 35457, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Lightning Reward Quest" }
quests[35458] = { id = 35458, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Lightning Reward Quest" }
quests[35459] = { id = 35459, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Southern Wilds", description = "Posted by: Prelate Reenu\n\nNoble friends of the Alliance, the draenei of The Draakorium greet you peacefully.\n\nThe Draakorium is being attacked by enemies from the nearby swamps.\n\nAn Azerothian caravan passed through recently, and may have ventured into dangerous territory.\n\nAny capable adventurer who can assist us with this problem will be rewarded handsomely.", completion = "Thank you for coming to assist us.", objectives = "Speak to Prelate Reenu at The Draakorium.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35460] = { id = 35460, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attack of the Iron Horde", description = "We received reports of the Dark Portal turning red right before the attack. They call themselves the Iron Horde, yet they seem to have no affiliation with the Horde we know.\n\nTheir army is extremely well equipped, and their numbers appear to be unending.\n\nThey have already taken Nethergarde Keep. Our troops on the frontlines could use your help, {class}.", completion = "Good form, champion. I'm sure your presence on the field was inspiring for our troops.", objectives = "Kill 8 Ironmarch Grunts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35461] = { id = 35461, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siege of Niuzao Reward Quest" }
quests[35462] = { id = 35462, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Under Siege", description = "Those Iron Horde cannons are laying waste to our troops. I'm not sure how much more of this we can handle. Our forces are already spread too thin.\n\nThere has to be a way to stop those war machines.", completion = "It will take the Iron Horde quite a while to get those demolishers operational again. Excellent work, {name}.", objectives = "Sabotage 3 Iron Demolishers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35463] = { id = 35463, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Subversive Scouts", description = "We have been unable to execute a vast majority of our battleplans. We are definitely being watched.\n\nThe Iron Horde must have scouts planted throughout the Blasted Lands. Victory is slipping away from us.", completion = "You killed how many scouts? No wonder we have been unable to execute our plans...", objectives = "Kill 5 Iron Horde scouts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35464] = { id = 35464, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ending Executions", description = "We arrived as soon as we could... but we are too late. Nethergarde has fallen. The Iron Horde has taken a number of Nethergarde warriors prisoner.\n\nNo doubt they are trying to squeeze vital information out of our troops.\n\nI fear once they are done with their interrogation they will not hesitate to execute their prisoners. Time is running out.", progress = "Did you kill the Ironmarch Executioners?", completion = "The prisoners are shaken up, but they are free. Their families are in your debt, {name}.", objectives = "Kill 3 Ironmarch Executioners", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35465] = { id = 35465, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Halls of Stone Reward Quest" }
