quests[35480] = { id = 35480, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Violet Hold Reward Quest" }
quests[35481] = { id = 35481, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Nizzix" }
quests[35482] = { id = 35482, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Admiral Taylor", description = "Admiral Taylor had figured out who was behind all this. He told us to save who we could... he wanted to handle matters himself.\n\nWe never heard from him again, but we have our orders.\n\nPlease... please find him. He went towards the farm.", completion = "From one commander to another... thank you.\n\nWe've been through a lot together, haven't we, {name}? Vashj'ir... the Jade Forest... Lion's Landing...\n\nI am truly honored that I could end my journey by your side.", objectives = "Find Admiral Taylor at Admiral Taylor's Farm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35483] = { id = 35483, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drak'Tharon Keep Reward Quest" }
quests[35484] = { id = 35484, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drak'Tharon Keep Reward Quest" }
quests[35486] = { id = 35486, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lunatic Lieutenants", description = "It is time we learned more about our new enemy.\n\nOur scouts have identified a number of the Iron Horde's lieutenants. Their attack is too organized to be run by tribal knowledge alone. Surely their lieutenants have access to secret battleplans. \n\nYou are the only soldier I can trust with this mission, {name}.", progress = "Were you able to gain access to any battleplans?", completion = "Let's take a look at these battleplans.", objectives = "Collect Iron Horde battleplans.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35487] = { id = 35487, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Burn the Dead", description = "I saw lots of bodies here. Kaz always said to burn the bodies.\n\nThat way they can't come back as the mean greens.\n\nWe should burn the bodies.", progress = "Hee hee.", completion = "That was stinky.", objectives = "Burn 6 Bodies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35488] = { id = 35488, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death to the Dreadmaul", description = "The stupidity of the Dreadmaul ogres never ceases to amaze me. The Iron Horde is clearly using them to further their own nefarious agenda.\n\nRegardless, we must show the ogres what happens when you confront the Alliance. I think it's time we send the Dreadmaul ogres a message.", completion = "It's important that our enemies understand what happens when you attack the Alliance. I'm glad you could be there to show them.", objectives = "Kill 8 Dreadmaul Ogres.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35489] = { id = 35489, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ahn'kahet: The Old Kingdom Reward Quest" }
quests[35490] = { id = 35490, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ahn'kahet: The Old Kingdom Reward Quest" }
quests[35491] = { id = 35491, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Flag - Underseer Bloodmane Vignette" }
quests[35492] = { id = 35492, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Nethergarde!", description = "The Iron Horde controls Nethergarde Keep, but they are fools if they think we will not return to claim our land.\n\nMy best troops are more than eager to spill the blood of those savages, but we need a champion like yourself to lead the charge.", completion = "The Iron Horde will learn to fear us, as they should.", objectives = "Plant the Alliance flags inside Nethergarde Keep.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35493] = { id = 35493, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ahn'kahet: The Old Kingdom Bonus Reward" }
quests[35494] = { id = 35494, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mementos of the Fallen", description = "There were so many of them. The guards couldn't stop them... nobody could stop them. So many souls stripped of their bodies by those savages.\n\nWe must not forget those that gave their lives to try and defend Nethergarde. Please, if you find any mementos of the fallen, bring them back to me.", progress = "Did you find anything?", completion = "Thank you, {name}. These mementos will forever remind us of the day we lost so many of our loved ones.", objectives = "Collect Strumner's Sword, Keri's Mug, and Krolan's Shield.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35495] = { id = 35495, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Toothsmash the Annihilator", description = "If the battleplans you brought back are true, the Dreadmaul ogres are as much to blame for this devastation as the Iron Horde. It's time we send those ogres a message.\n\nIt looks like the Iron Horde's main contact is a large ogre in Dreadmaul named Toothsmash. Killing him will put a dent in their battleplans.", completion = "Toothsmash is dead? Good, I'm sure it will take the Iron Horde a while to find another ogre smart enough to help them with their efforts.", objectives = "Kill Toothsmash the Annihilator", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35496] = { id = 35496, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Enohar's Revenge", description = "They... they killed my sister. Those beasts marched right through the front gates and... it was horrible.\n\nThe Dreadmaul ogres stood beside them during the attack. They will all suffer. Here take this poison, place a couple drops in their rat stew. The poison will slowly eat away at their insides. Causing a prolonged and painful death, just like they deserve.\n\nPlease, for my sister.", completion = "I wish I could be there to watch their faces as they suffer. I hope they all die a slow horrible death.", objectives = "Poison the Dreadmaul ogre food supply.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35497] = { id = 35497, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azjol-Nerub Reward Quest" }
quests[35498] = { id = 35498, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azjol-Nerub Reward Quest" }
quests[35499] = { id = 35499, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blow up towers", description = "xxxxx" }
quests[35500] = { id = 35500, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gar'mak Bladetwist", description = "With the intelligence you have gathered we have learned this assault is being led by a powerful Iron Horde orc named Gar'mak Bladetwist. He is hunkered down inside Okril'lon Hold.\n\nKilling him will not win this war, but it will surely break down the Iron Horde's communication. This will buy us valuable time while we gather more forces and outline a battleplan to deal with this new threat.", completion = "It was an honor fighting alongside of you, {name}.", objectives = "Kill Gar'mak Bladetwist.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35501] = { id = 35501, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doomshot", description = "This ominously large explosive appears to be ammunition for the primary cannon that the Bastion is built around.\n\nThe loading assembly must be on a lower floor, but this ammo did not make it that far.", progress = "This loader can take a number of rounds of doomshot at a time.", completion = "The rounds of doomshot fit into the weapon loader with ease.", objectives = "Collect 4 Doomshot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35502] = { id = 35502, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Utgarde Keep Reward Quest" }
quests[35503] = { id = 35503, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Char the Burning" }
quests[35504] = { id = 35504, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iron Joker" }
quests[35505] = { id = 35505, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Lumberjack", description = "Me friend was in the mole machine wit' me. Good ol' Frenna tried to make the best of it by writin' all o' her observations down in a journal.\n\nPenny here wants me to tell ya where she is. I cannae say for sure, but she was followin' me outta here and I don't think she made it.", completion = "Frenna didn't make it out of Tangleheart.", objectives = "Find Frenna within Tangleheart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35506] = { id = 35506, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Growing Wood", description = "I found this dwarf, Thuldren, runnin' out of Tangleheart like his boots were on fire.\n\nSays his mole machine showed up here and he barely made it out alive. And another called Frenna might still be inside.\n\nOne useful thing he told me is that the creatures in there have sap that can be used to grow things real fast.\n\nBy the way, I'm gonna go lookin' for Thuldren's mole machine. Find me in Tangleheart when you're done.", progress = "Don't be such a sap. Get it?!", completion = "You got it! You should be able to use this mole machine one way back to your outpost.", objectives = "Collect 100 Ancient Growth Sap from botani or ancients within Tangleheart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35507] = { id = 35507, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down the Goren Hole", description = "Dwarves are dumb. Don't they know that if you dig a deep hole you are going to have goren attack?\n\nIf you are going to go into that iron fort you better kill a bunch of goren otherwise they are going to chew the walls enough to cause a cave-in.\n\nI would do it myself but I'm still stuffed from all that fruit the botani made me eat.", progress = "Goren like to chew things. I HATE THAT!", completion = "Goren, goren, gone!", objectives = "Slay 7 goren in Moira's Bastion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35508] = { id = 35508, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chapter I: Plant Food", description = "There are strange, glowing objects within Tangleheart, seemingly pollinated by a variety of stinging creature.\n\nThe botani sometimes collect whatever the pods produce. I can't be sure what it is, but it might be dangerous to us.\n\n- Frenna", completion = "Hey, nice job commander!", objectives = "Destroy 8 Pollen Pods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35509] = { id = 35509, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Will of the Genesaur", description = "I am pretty sure those dwarves took the artifact in that iron fort there.\n\nAre you going to go get it?", progress = "Kaz said she wants me to hide for this fight.", completion = "The genesaur is coming!", objectives = "Recover the Will of the Genesaur.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35510] = { id = 35510, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iyu", description = "There is a genesaur here!\n\nIt wants its artifact back.\n\nKaz and Draka are fighting it now on the surface but they need you. Draka said I could fire the big gun. So I will stay here and do that.", progress = "Was the shaman being truthful?", completion = "It was an honor to fight by your side today, commander.", objectives = "Defeat Iyu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35511] = { id = 35511, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaz the Shrieker", objectives = "Commander, you go where you will and kill any who would stand in your way.\n\nI find this fun.\n\nI wish to join your... \"followers\"... as the lady wolf keeps calling them.\n\nMy home is crushed, my family mulched, and this place has lost its charm.\n\nLet me join you.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
