quests[35523] = { id = 35523, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Morva Soultwister" }
quests[35524] = { id = 35524, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chapter III: Ritual of the Charred", description = "I have seen a strange ritual performed by ancients. They step into fire, burning the leaves from their branches and charring their bark.\n\nI call it the Ritual of the Charred. If we want to weaken the ancients, we can get rid of them before they become even stronger.\n\n- Frenna", completion = "You saw 'em burn off their own leaves? That'd be like me cutting off my cute-as-a-button pigtails!", objectives = "Kill 4 Ancients.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35525] = { id = 35525, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Botanica Reward Quest" }
quests[35526] = { id = 35526, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Botanica Reward Quest" }
quests[35527] = { id = 35527, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chapter II: The Harvest", description = "I have seen a creature working with the ancient saplings, imbuing them with anger and hatred toward creatures unlike them.\n\nPerhaps it is this botani who is responsible for the unusually aggressive nature of ancients here in Tangleheart.\n\nWould killing this botani do us good? I fear I would be no match for it alone.\n\n- Frenna", completion = "Big baddy botani busted? Works for me!", objectives = "Kill Ontogen the Harvester.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
