quests[35535] = { id = 35535, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Arcatraz Reward Quest" }
quests[35536] = { id = 35536, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of the Botani", description = "The botani must have stuck that big ogron there to protect something fancy. And what was that stumpy looking creature that it killed?\n\nThe botani are mean, but they have some fun toys. Maybe Kaz might know what it was.\n\nCan we go find Kaz now?\n\nI saw a compost heap up the south hill. If Kaz came looking for me I bet she would start there.", completion = "You found my Cutter! I shall gladly cut a thousand throats in your honor.", objectives = "Escort Cutter to Kaz the Shrieker at the Compost Heap.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35537] = { id = 35537, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "News from Spires of Arak", description = "Commander, scouts from Spires of Arak have brought back news to the garrison. There's word of a brewin' war between bird-men and the Shattered Hand orcs.\n\nRokhan's askin' for your presence when your work is done here, should ya be willin' sir.", completion = "Welcome back, boss-mon.\n\nI know you'll probably be wantin' to get things settled here first, but there's been some word of an uprisin' in Spires of Arak. There might be some allies to be made if we get involved.\n\nThought ya might want to know.", objectives = "Speak to Rokhan at your garrison in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
