quests[35548] = { id = 35548, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mana-Tombs Bonus Objective" }
quests[35549] = { id = 35549, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honoring a Hero", description = "By the Light...\n\nI can't believe this happened to Taylor and his men when they had a full garrison.\n\nIt's going to take everything we have to keep your outpost safe, commander.\n\nWe should get out of here. We can honor the fallen when we're safe.", completion = "We will never forget Admiral Taylor's sacrifices for the greater good.", objectives = "Speak to Lieutenant Willem at Southport.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35550] = { id = 35550, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surviving in a Savage Land", description = "Dey may be Alliance, but Admiral Taylor and his men fought with honor on da battlefield.\n\nDey deserve our respect, warchief be praised.\n\nIf an entire garrison be fallin' to dark magic, our work be cut out for us, eh commander?\n\nWe should be goin' back to base. It safe there.\n\nSafer, anyway.", completion = "Ukambe gave me the report, commander. You truly are the champion of the Horde.", objectives = "Speak to Taskmaster Gornek at Axefall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35552] = { id = 35552, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trust No One", description = "Nothing is the same since I returned. There is always whispering - everywhere, whispering. Maraad cannot see it, but there are even traces of fel energy here in Elodor. We have been infiltrated!\n\nI must attend to the Exarch Council, but I need you to investigate. Follow the traces of fel energy that I will illuminate. If there are truly traitors in our midst, they will have to have some sort of hideout. Find it! I will wait for you with the other Exarchs.", completion = "A flesh-bound book lies on an unholy altar. Your skin crawls. Maladaar was right!", objectives = "Follow Maladaar's trail to verify that Elodor has been infiltrated.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35553] = { id = 35553, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Rai'vosh" }
quests[35554] = { id = 35554, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "News from Spires of Arak", description = "While you were gone, a rather shady looking human arrived at the outpost asking for you. He said he worked for... Grey was it?... and had some information regarding Spires of Arak that you would be interested in.\n\nHe was heading back to your garrison and asked that I passed along the message, and so I have.\n\nAnd before you go, thank you for all you've done for us here, truly. You and your army have turned the tides of a war that you could have just as easily walked away from. We will not forget.", completion = "Welcome back, commander.\n\nI know you'll probably want to get things settled here first, but there's been some word of an uprising in Spires of Arak. If we act fast, we might be able to make some new allies against the Iron Horde.\n\nI'll have the scouts keep an ear out for any more news. That's it for now, sir.", objectives = "Speak to Bodrick Grey at your garrison in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35555] = { id = 35555, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Darktalon" }
quests[35556] = { id = 35556, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Secrets of Gorgrond", description = "Commander, Yrel and Maraad have a tactical suggestion.\n\nThey recommend a small expedition group be sent into the savage wastelands of Gorgrond far to the north.\n\nReports from their rangari suggest that land may hold ancient secrets or primal knowledge that we might use to exploit weaknesses in the Iron Horde that our enemy would not expect.\n\nIf you wish to go I will have a gryphon prepared for you at once.", completion = "Welcome to Gorgrond, Commander. We only just arrived ourselves.", objectives = "Seek Yrel at the Wildwood Wash in Gorgrond. Speak with your Garrison Gryphon Master to fly there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35557] = { id = 35557, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Secrets of Gorgrond", description = "Commander, Durotan calls for aid in leading a small strike team into Gorgrond to launch a counter attack against the Iron Horde strongholds there.\n\nThe land is home to the Blackrock clan, industrial arm of the Iron Horde.\n\nIt is also home to some of the most savage giants and monsters in all of Draenor.\n\nIf you wish to answer this call to action, Gorgrond can be reached through the eastern side of Frostfire Ridge through Thunder Pass.", completion = "Gorgrond is no place for armies, Commander. We are now stepping into the domain of legends.", objectives = "Meet Durotan in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35558] = { id = 35558, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Hypnocroak" }
